+function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
+  const limitResult = parseListLimit(message.limit);
+  if (!limitResult.ok) return {valid: false, error: limitResult.error};
+
+  const cursorResult = parseListCursor(message.before);
+  if (!cursorResult.ok) return {valid: false, error: cursorResult.error};
+
+  return {
+    valid: true,
+    data: {
+      type: 'list_sessions',
+      ...(limitResult.limit !== undefined ? {limit: limitResult.limit} : {}),
+      ...(cursorResult.before !== undefined ? {before: cursorResult.before} : {}),
+    },
+  };
+}
+
+type ParsedLimit = {ok: true; limit: number | undefined} | {ok: false; error: string};
+
+function parseListLimit(rawLimit: unknown): ParsedLimit {
+  if (rawLimit === undefined) return {ok: true, limit: undefined};
+  if (typeof rawLimit !== 'number' || !Number.isInteger(rawLimit) || rawLimit < 0) {
+    return {ok: false, error: 'list_sessions limit must be a non-negative integer'};
+  }
+  return {ok: true, limit: rawLimit};
+}
+
+type ParsedCursor = {ok: true; before: ListSessionsMessage['before']} | {ok: false; error: string};
+
+function parseListCursor(rawBefore: unknown): ParsedCursor {
+  if (rawBefore === undefined) return {ok: true, before: undefined};
+  if (!isPlainRecord(rawBefore)) {
+    return {ok: false, error: 'list_sessions before must be an object'};
+  }
+
+  const {sessionId, updatedAt} = rawBefore;
+  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_SESSION_ID_LENGTH) {
+    return {ok: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
+  }
+  if (!isUsableTimestamp(updatedAt)) {
+    return {ok: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
+  }
+
+  return {ok: true, before: {updatedAt, sessionId}};
+}
+
+function isPlainRecord(candidate: unknown): candidate is Record<string, unknown> {
+  return typeof candidate === 'object' && candidate !== null && !Array.isArray(candidate);
+}
+
+function isUsableTimestamp(stamp: unknown): stamp is string | number {
+  if (typeof stamp !== 'string' && typeof stamp !== 'number') return false;
+  return Number.isFinite(new Date(stamp).getTime());
+}
