describe("listing a user's sessions", () => {
  const errors = captureErrors();

  it('answers list_sessions with ISO summaries for session.userId, empty when unimplemented, and SERVER_ERROR before any queued pong when listFor rejects', async () => {
    const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const before: SessionCursor = {updatedAt: '2026-03-10T10:00:00.000Z', sessionId: 'conv-9'};
    const listed = await sendFramesWithStore(
      {
        ...stubStore(),
        listFor: (userId, options) => {
          calls.push({userId, options});
          return [storedSummary()];
        },
      },
      [{type: 'list_sessions', limit: 5, before, userId: 'other-user'}]
    );
    const omitted = await sendFramesWithStore(undefined, [{type: 'list_sessions'}]);
    const unimplemented = await sendFramesWithStore(stubStore(), [{type: 'list_sessions'}]);
    const failed = await sendFramesWithStore(
      {...stubStore(), listFor: () => Promise.reject(new Error('store unreachable'))},
      [{type: 'list_sessions'}, {type: 'ping', timestamp: 5}]
    );

    expect({
      calls,
      listed,
      omitted,
      unimplemented,
      failed: wire(failed),
      errors,
    }).toEqual({
      calls: [{userId: 'u1', options: {limit: 5, before}}],
      listed: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 'conv-7',
              createdAt: '2026-03-10T08:00:00.000Z',
              updatedAt: '2026-03-10T09:15:00.000Z',
              entryCount: 3,
            },
          ],
        },
      ],
      omitted: [{type: 'session_list', sessions: []}],
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: ['error SERVER_ERROR', 'pong 5'],
      errors: [
        {
          category: 'ws',
          message: 'session list failed',
          userId: 'u1',
          error: 'store unreachable',
        },
      ],
    });
  });
});

